/*
    ARCHIVO GENERADO por Sql/Tools/generate_knowledge_base.ps1 a partir de las tablas BDC_* de la máquina
    de inferencia del equipo (Visual FoxPro, P-160). No editar a mano: corregir los DBF y volver a generar.

    Agrega a ENFERMEDADES, SINTOMAS, SIGNOS y TRATAMIENTOS los registros que falten (por ID), en una sola
    transacción. No modifica ni borra los existentes, así que se puede correr varias veces.
    Correr DESPUÉS de SeedClinicalData.sql: ese script borra y recarga las tablas clínicas.

    Origen: 924 enfermedades, 2350 síntomas, 2827 signos y 4416 tratamientos;
    613 textos partidos por una coma se reunieron (ver el generador).
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;

IF DB_NAME() IN (N'master', N'model', N'msdb', N'tempdb')
    THROW 50010, 'Selecciona la base de datos XpertDiagnostic antes de ejecutar este script.', 1;

CREATE TABLE #Enfermedades (Id_Enfermedad VARCHAR(10) NOT NULL PRIMARY KEY, Nombre NVARCHAR(150) NOT NULL);
CREATE TABLE #Sintomas (Id VARCHAR(20) NOT NULL PRIMARY KEY, Id_Enfermedad VARCHAR(10) NOT NULL, Descripcion NVARCHAR(300) NOT NULL, LimiteInferior DECIMAL(12,2) NULL, LimiteSuperior DECIMAL(12,2) NULL, Unidades NVARCHAR(30) NULL);
CREATE TABLE #Signos (Id VARCHAR(20) NOT NULL PRIMARY KEY, Id_Enfermedad VARCHAR(10) NOT NULL, Descripcion NVARCHAR(300) NOT NULL, LimiteInferior DECIMAL(12,2) NULL, LimiteSuperior DECIMAL(12,2) NULL, Unidades NVARCHAR(30) NULL);
CREATE TABLE #Tratamientos (Id VARCHAR(20) NOT NULL PRIMARY KEY, Id_Enfermedad VARCHAR(10) NOT NULL, Descripcion NVARCHAR(300) NOT NULL, DosisMinima DECIMAL(12,2) NULL, DosisMaxima DECIMAL(12,2) NULL, Unidades NVARCHAR(30) NULL);

