BEGIN TRANSACTION;

INSERT INTO dbo.ENFERMEDADES (Id_Enfermedad, Nombre)
SELECT t.Id_Enfermedad, t.Nombre FROM #Enfermedades AS t
WHERE NOT EXISTS (SELECT 1 FROM dbo.ENFERMEDADES AS e WHERE e.Id_Enfermedad = t.Id_Enfermedad);
PRINT 'Enfermedades agregadas: ' + CAST(@@ROWCOUNT AS varchar(10));

INSERT INTO dbo.SINTOMAS (Id_Sintoma, Id_Enfermedad, Descripcion, LimiteInferior, LimiteSuperior, Unidades)
SELECT t.Id, t.Id_Enfermedad, t.Descripcion, t.LimiteInferior, t.LimiteSuperior, t.Unidades FROM #Sintomas AS t
WHERE NOT EXISTS (SELECT 1 FROM dbo.SINTOMAS AS s WHERE s.Id_Sintoma = t.Id);
PRINT 'Síntomas agregados: ' + CAST(@@ROWCOUNT AS varchar(10));

INSERT INTO dbo.SIGNOS (Id_Signo, Id_Enfermedad, Descripcion, LimiteInferior, LimiteSuperior, Unidades)
SELECT t.Id, t.Id_Enfermedad, t.Descripcion, t.LimiteInferior, t.LimiteSuperior, t.Unidades FROM #Signos AS t
WHERE NOT EXISTS (SELECT 1 FROM dbo.SIGNOS AS s WHERE s.Id_Signo = t.Id);
PRINT 'Signos agregados: ' + CAST(@@ROWCOUNT AS varchar(10));

INSERT INTO dbo.TRATAMIENTOS (Id_Tratamiento, Id_Enfermedad, Descripcion, DosisMinima, DosisMaxima, Unidades)
SELECT t.Id, t.Id_Enfermedad, t.Descripcion, t.DosisMinima, t.DosisMaxima, t.Unidades FROM #Tratamientos AS t
WHERE NOT EXISTS (SELECT 1 FROM dbo.TRATAMIENTOS AS s WHERE s.Id_Tratamiento = t.Id);
PRINT 'Tratamientos agregados: ' + CAST(@@ROWCOUNT AS varchar(10));

COMMIT TRANSACTION;

DROP TABLE #Enfermedades; DROP TABLE #Sintomas; DROP TABLE #Signos; DROP TABLE #Tratamientos;
